{
  "headline": "Filgrastim is not on FDA's shortage list; Corvale General has 17.1 days on hand and the top buying option is Sandoz Inc.",
  "headline_cites": ["D2", "D1", "D3"],
  "sentences": [
    {
      "text": "FDA's drug shortage list does not include filgrastim as of 2026-10-21.",
      "cites": ["D2"]
    },
    {
      "text": "Corvale General holds 49 vials of the 480 ug/1.6 mL presentation, which at a daily use of 2.9 vials provides 17.1 days on hand.",
      "cites": ["D1"]
    },
    {
      "text": "The rule‑ranked first option is to buy from Sandoz Inc., which is also not on the shortage list today.",
      "cites": ["D3"]
    },
    {
      "text": "A secondary option is to buy from Tanvex BioPharma USA, Inc., also not listed on the shortage list.",
      "cites": ["D4"]
    },
    {
      "text": "A third option is Accord BioPharma Inc., whose label names no plant we could place.",
      "cites": ["D5"]
    },
    {
      "text": "One label for a related product names Kashiv BioSciences, LLC (FEI 3011289655) as a registered plant with operations including manufacture and analysis, last inspected with a VAI classification on 2024-06-14.",
      "cites": ["E5"]
    },
    {
      "text": "FDA inspection records for that plant show a VAI in 2015, an OAI in 2018, and the most recent VAI in 2024.",
      "cites": ["E2", "E3", "E4"]
    }
  ]
}
